// --- Pure's model tier -------------------------------------------
//
// Random sequences of Pure's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and PureSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — no reader/writer pair derives a store,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Describe (pure)
//	Not bound:
//	           pure differential — the reference is the subject's own factory, whose comparison already rides each law leg's actions; alone it catches nondeterminism and nothing a second instance shares
//
// pureModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func pureModelActions() []model.Action[Pure] {
	out := []model.Action[Pure]{
		action.Pure("Describe",
			func(s pure.Pure) string {
				return s.Describe()
			}),
	}
	return out
}

// pureAssertPureDeterministic binds AUTO-PURE-DETERMINISTIC over the shared sequences.
//
// One law, and the run's only oracle — see [legs.Law]
// for why the differential is off on every law leg.
func pureAssertPureDeterministic(
	tb testing.TB,
	sub suite.Subject[Pure],
) {
	tb.Helper()

	buildRef, tier := legs.Reference(tb, sub, func() Pure { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Pure { return sub.New(tb) }, buildRef,
		pureModelActions(),
		[]law.Law[Pure]{
			law.PureDeterminism[pure.Pure, string]{
				Call: func(rt *model.T, s pure.Pure) string {
					return s.Describe()
				},
			},
		})
}

